class ImagePathHandler{static get API_BASE_URL(){return window.APP_CONFIG?.api?.baseURL||"http://localhost:8080"}static get DEFAULTS(){return{USER:"../assets/default-user-profile.jpg",PET:"../assets/default-pet-profile.jpg"}}static processImagePath(t,e=this.DEFAULTS.USER){return t?t.startsWith("http")||t.startsWith("../assets/")?t:t.startsWith("/api/static/")?`${this.API_BASE_URL}${t}`:e:e}static processPetImagePath(t){return this.processImagePath(t,this.DEFAULTS.PET)}static processUserImagePath(t){return this.processImagePath(t,this.DEFAULTS.USER)}static createImageElement(t,e="",s=this.DEFAULTS.USER){const a=document.createElement("img"),r=this.processImagePath(t,s);return a.src=r,a.alt=e,a.onerror=function(){this.src!==s&&(this.src=s)},a}}"undefined"!=typeof module&&module.exports&&(module.exports=ImagePathHandler),"undefined"!=typeof window&&(window.ImagePathHandler=ImagePathHandler);